Method.Implementation:
$$$TRACE("OnMessage.")
Set ..MinimumSequenceNumber=$ZSTRIP(..MinimumSequenceNumber,"<>W") $$$TRACE("Current Minimum Sequence Number is "_..MinimumSequenceNumber) Set ..MaximumSequenceNumber=$ZSTRIP(..MaximumSequenceNumber,"<>W") $$$TRACE("Current Maximum Sequence Number is "_..MaximumSequenceNumber)
Quit:'$IsObject(pRequest.Stream) $$$ERROR($$$EnsErrGeneral,"No Stream contained in StreamContainer Request") Set tNameIn=##class(%File).GetFilename(pRequest.OriginalFilename)
Set (tFilename,tFinalFilename)=..Adapter.CreateTimestamp(tNameIn,..Filename) $$$TRACE("AfterCreateTimeStamp - tFinalFilename="_tFinalFilename) If ""'=..TempFilename { Set tFilename=..Adapter.CreateTimestamp(tNameIn,..TempFilename) }
Set currentDate = $ZDATETIME($ZTIMESTAMP,3,1,3) Set extractDate = $EXTRACT(currentDate,0,10) Set extractTime = $EXTRACT(currentDate,12,$LENGTH(currentDate))
$$$TRACE("BeforeSetAt - tFinalFilename="_tFinalFilename) do ..valueToBeReplaced.SetAt(tFinalFilename,"%f") do ..valueToBeReplaced.SetAt(extractDate,"%CD") do ..valueToBeReplaced.SetAt(extractTime,"%CT")
//Replace %Q with the current time in the same format Ensemble's %Q Uses: not white space and periods between the values do ..valueToBeReplaced.SetAt($REPLACE($ZSTRIP(extractDate_"_"_extractTime,"*W"),":","."),"%Q") do ..valueToBeReplaced.SetAt(^ItfGlobal(..%ConfigName, "CurrentSequenceNumber"),"%#")
Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject) Set updatedFailureEmailSubject = ..replaceWithParticularFormat(..FailureEmailSubject) Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody) Set updatedFailureEmailbody = ..replaceWithParticularFormat(..FailureEmailBody) //Set tFinalFilename = ..replaceWithParticularFormat(tFinalFilename) Set UpdatedActionOnTargetFile = ..replaceWithParticularFormat(..ActionOnTargetFile)
Set tFinalFilename = ..replaceWithParticularFormat(tFinalFilename)
Set UpdatedActionOnTargetFile = ..replaceWithParticularFormat(..ActionOnTargetFile)
Set tSC=..Adapter.PutStream(tFilename, pRequest.Stream)
//Note: the following line is intended to skip this block if the ActionOnTargetFile field is empty, This is the intended behavior if ""'=..ActionOnTargetFile{ $$$TRACE("IHC.ITF.ITFCOMMON.FTP.Operation.PassthroughOperation1: Adapter.Rename("_tFinalFilename_","_UpdatedActionOnTargetFile_","_..Adapter.FilePath_")") do ..Adapter.Rename(tFinalFilename,UpdatedActionOnTargetFile,..Adapter.FilePath) }
// For this Retry logic to work, Operation Setting "Reply Code Actions" should have a code with R , e.g E=RD or E=RF $$$TRACE("Current Retry Count : "_..RetryCount) set MaxRetry = (..FailureTimeout/..RetryInterval)+1 $$$TRACE(..FailureTimeout_" **** "_..RetryInterval_" ***** "_"Max retry : "_MaxRetry)
$$$TRACE("Retry:"_..Retry) $$$TRACE("FailureTimeOut:"_..FailureTimeout)
//Assign default permissions if none are specified
if (""=..FilePermissions && $$$ISOK(tSC)) { $$$TRACE("Setting permissions for "_UpdatedActionOnTargetFile_" to be ug+rwx") $$$TRACE("IHC.ITF.ITFCOMMON.Operation.PassthroughOperation1..Adapter.SetPermissions("_UpdatedActionOnTargetFile_",ug+rwx)") Set tSC=..Adapter.SetPermissions(UpdatedActionOnTargetFile,"ug+rwx") }
if (""'=..FilePermissions && $$$ISOK(tSC)) { //If we don't have any errors yet $$$TRACE("Setting permissions for "_UpdatedActionOnTargetFile_" to be "_..FilePermissions) $$$TRACE("IHC.ITF.ITFCOMMON.Operation.PassthroughOperation1..Adapter.SetPermissions("_UpdatedActionOnTargetFile_","_..FilePermissions_")") Set tSC=..Adapter.SetPermissions(UpdatedActionOnTargetFile,..FilePermissions) }
//Sending Email If $$$ISOK(tSC) { $$$TRACE("Sending alert for successful file transfer.") do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody) } ElseIf(..RetryCount=MaxRetry) { $$$TRACE(MaxRetry_" Retry Count inside else part : "_..RetryCount) $$$TRACE("Sending alert for failure in file transfer.") do ..valueToBeReplaced.SetAt(tSC,"%EM") Set updatedFailureEmailSubject = ..replaceWithParticularFormat(updatedFailureEmailSubject) Set updatedFailureEmailbody = ..replaceWithParticularFormat(updatedFailureEmailbody) do ..ItfSendEmailOnError(updatedFailureEmailSubject, updatedFailureEmailbody) $$$TRACE("Error ocurred processing file: "_..Adapter.FilePath_"/"_UpdatedActionOnTargetFile_". Shutting down the component.") //Disable the operation Job ##class(Ens.Director).EnableConfigItem(..%ConfigName,0,1) }
do ..IncrementSequenceNumber() Quit tSC

$$$TRACE("..ResetSequenceOnRestart="_..ResetSequenceOnRestart)
//If we are resetting the sequence number because the user wants us to or one is not configured
if ((..ResetSequenceOnRestart) || ($DATA(^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")) = "0")) {
	//If there is a configured starting sequence number, replace the current number with it, or use the default
	if (""'=..StartingSequenceNumber) {
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..StartingSequenceNumber
		$$$TRACE("Replacing sequence number with starting sequence number: "_^ItfGlobal(..%ConfigName, "CurrentSequenceNumber"))
	}
	//If there is no configured starting sequence number, use a default
	else {
		$$$TRACE("No sequence numbers defined; setting to a default of 1")
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")=	"1"
	}
}
else {
	$$$TRACE("CurrentSequenceNumber is "_^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")_" and ResetSequenceOnRestart is disabled. Sequence number will not be reset")
}
Do ..VerifySequenceNumber()


if ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") < ..MinimumSequenceNumber //If sequence number is too low
{
	if ..SequenceIncrement < 0  { //If sequence number is too low and is descending, reset to maximum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MaximumSequenceNumber
		$$$TRACE("Sequence number has descended to below minimum value. Wrapping back to maximum value: "_..MaximumSequenceNumber)
	}
	if ..SequenceIncrement > 0 { //If sequence number is ascending, move to minimum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MinimumSequenceNumber
		$$$TRACE("Sequence number is beneath its minimum value.  Setting to minimum value: "_..MinimumSequenceNumber)
	}
}

if ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") > ..MaximumSequenceNumber //If sequence number is too high
{
	if ..SequenceIncrement < 0  {//If sequence number is too high and descending, set to maximum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MaximumSequenceNumber
		$$$TRACE("Sequence number is above maximum value, but descending. Setting to maximum value: "_..MaximumSequenceNumber)
	}
	if ..SequenceIncrement > 0 {// If sequence number is too high and ascending, reset to minimum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MinimumSequenceNumber
		$$$TRACE("Sequence number has ascended to above maximum value.  Wrapping back to minimum value: "_..MinimumSequenceNumber)
	}
}
if ..MinimumSequenceNumber > ..MaximumSequenceNumber //If the minimum and maximum violate each other
{
	$$$TRACE("MinimumSequnceNumber is greater than the MaximumSequnceNumber; setting CurrentSequenceNumber to zero.")
 	Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = 0
}
